{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Compassionate, practical therapy for anxiety, relationships, trauma, and life transitions in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="nav">
    <div class="container nav-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="desktop-nav">
        <a href="about.html">About</a>
        <a href="specialties.html">Work With Me</a>
        <a href="approach.html">My Approach</a>
        <a href="fees.html">Fees</a>
        <a href="faq.html">FAQ</a>
        <a class="cta small" href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
      <button class="nav-toggle" aria-label="Toggle menu">☰</button>
    </div>
    <div class="mobile-nav hidden">
      <a href="about.html">About</a>
      <a href="specialties.html">Work With Me</a>
      <a href="approach.html">My Approach</a>
      <a href="fees.html">Fees</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      <a href="contact.html">Contact</a>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1 class="hero-title">Calm-forward therapy for busy, sensitive people</h1>
          <p class="hero-sub">I help you untangle what matters most — anxiety, relationships, burnout, and transitions — with practical tools and steady support.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="about.html">Meet {{THERAPIST_NAME}}</a>
          </div>
          <ul class="hero-stats">
            <li>Telehealth &amp; in-person in {{CITY}}, {{STATE}}</li>
            <li>Specializing in anxiety, trauma, relationships</li>
            <li>Confidential, evidence-informed care</li>
          </ul>
        </div>
        <div class="hero-art">
          <img src="assets/img/hero.svg" alt="Abstract supportive illustration">
        </div>
      </div>
    </section>

    <!-- Story -->
    <section class="story container" id="story">
      <div class="story-inner">
        <div class="avatar">
          <img src="assets/img/avatar.svg" alt="Portrait illustration of therapist">
        </div>
        <div class="story-copy">
          <h2>Hi — I’m {{THERAPIST_NAME}}</h2>
          <p>I’m a licensed clinician ({{LICENSE}}) offering short- and long-term therapy. I aim to create a practical, warm space where we address symptoms and the life context behind them. I combine mindfulness, cognitive-behavioral tools, and relational focus to support steady change.</p>
          <p>My work centers on safety, collaboration, and clear goals. If you’re looking to manage anxiety, recover from relational wounding, navigate transitions, or reduce burnout, we’ll build a plan that fits your life.</p>
          <p class="muted">I offer telehealth and in-office sessions in {{CITY}}, {{STATE}}. Confidentiality is central: your records are private and protected by professional ethical standards.</p>
        </div>
      </div>
    </section>

    <!-- Framework -->
    <section class="framework container" id="framework">
      <h2>How I work — a steady framework</h2>
      <p class="lead">Therapy can feel overwhelming. I use a clear, three-part framework so we both know where we are and what we’re working toward.</p>
      <div class="grid">
        <div class="card">
          <h3>1. Map</h3>
          <p>We identify patterns, triggers, and goals. You’ll get a clear sense of what keeps things stuck and what’s possible.</p>
        </div>
        <div class="card">
          <h3>2. Skills</h3>
          <p>Practical tools for managing distress: grounding, breathing, cognitive shifts, and boundary practice tailored to your life.</p>
        </div>
        <div class="card">
          <h3>3. Integration</h3>
          <p>We build habits that fit your rhythms so change lasts — not quick fixes, but reliable progress you can trust.</p>
        </div>
      </div>
    </section>

    <!-- Programs -->
    <section class="programs container" id="programs">
      <h2>Paths &amp; Programs</h2>
      <p class="lead">Different rhythms for different needs. Each path includes a collaborative intake, tailored sessions, and home practice.</p>
      <div class="program-grid">
        <article class="prog">
          <h3>Compose — Short-term Focus (8 weeks)</h3>
          <p>Targeted support for a specific problem: anxiety spikes, a pattern in relationships, or an immediate life transition.</p>
          <a class="btn small" href="book.html">Start Compose</a>
        </article>
        <article class="prog">
          <h3>Rootwork — Deep Stabilization (12+ weeks)</h3>
          <p>Longer, steady work for trauma recovery, chronic anxiety, or rebuilding after major life changes.</p>
          <a class="btn small" href="book.html">Begin Rootwork</a>
        </article>
        <article class="prog">
          <h3>Coaching Blend — Skills + Check-ins</h3>
          <p>Weekly-to-monthly mix for professionals juggling career, caregiving, and personal goals who need flexible support.</p>
          <a class="btn small" href="book.html">Explore Blend</a>
        </article>
      </div>
    </section>

    <!-- Pricing -->
    <section class="pricing container" id="pricing">
      <h2>Investment &amp; Scheduling</h2>
      <p class="lead">Rates are transparent. Insurance may be accepted; reach out for specifics. Sliding scale spots available for limited availability.</p>
      <div class="price-grid">
        <div class="price-card">
          <h3>Intro Session</h3>
          <p class="price">$160 · 50 min</p>
          <p>Intake session to map goals and logistics.</p>
        </div>
        <div class="price-card">
          <h3>Standard Therapy</h3>
          <p class="price">$140 · 45 min</p>
          <p>Weekly or biweekly sessions, steady support and skills work.</p>
        </div>
        <div class="price-card">
          <h3>Extended Session</h3>
          <p class="price">$200 · 75 min</p>
          <p>Deeper work, couples sessions, or added integration time.</p>
        </div>
      </div>
      <p class="muted">Payments accepted via card. If finances are a barrier, please inquire about limited sliding-scale options.</p>
    </section>

    <!-- Testimonials -->
    <section class="testimonials container" id="testimonials">
      <h2>What clients say</h2>
      <div class="test-grid">
        <blockquote>
          <p>"Practical tools and a calm presence. I learned to notice triggers and actually change my day-to-day."</p>
          <cite>— J.S., client</cite>
        </blockquote>
        <blockquote>
          <p>"Sessions felt like a partnership: clear goals, honest feedback, and steady progress."</p>
          <cite>— A.L., client</cite>
        </blockquote>
        <blockquote>
          <p>"I appreciated the real-world strategies and how therapy fit my schedule as a parent and manager."</p>
          <cite>— M.R., client</cite>
        </blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta container" id="cta">
      <div class="cta-inner">
        <div>
          <h2>Ready to start?</h2>
          <p>Schedule a brief consultation to see if we’re a fit. I keep availability for new clients each month.</p>
        </div>
        <div>
          <a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <p class="muted">Or call <a href="tel:{{PHONE}}">{{PHONE}}</a> — email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <p class="brand">{{BUSINESS_NAME}}</p>
        <p class="muted">Licensed clinician: {{LICENSE}} · {{CITY}}, {{STATE}}</p>
      </div>
      <div>
        <p>Confidentiality &amp; privacy: Your sessions and records are protected by ethical standards and privacy law. I do not share session content without your consent except where required by law.</p>
      </div>
      <div>
        <p class="muted">Crisis disclaimer: If you are in crisis or danger, contact local emergency services or a crisis line immediately. Therapy is not a substitute for emergency care.</p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
