{"path":"assets/css/styles.css","content":"/* Bold Playful theme — compact stylesheet */
:root{
  --bg:#ffffff;
  --muted:#6b6b6b;
  --text:#0f1724;
  --accent:#ff7a59;
  --accent-2:#3b82f6;
  --card:#fff6f4;
  --radius:12px;
  --container:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; color:var(--text); background:var(--bg); line-height:1.45}
.container{max-width:var(--container);margin:0 auto;padding:24px}
.nav{background:linear-gradient(90deg,rgba(255,122,89,0.06),transparent);border-bottom:1px solid #fff3f0}
.nav-inner{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--text);text-decoration:none;font-size:1.05rem}
.desktop-nav a{margin-left:18px;text-decoration:none;color:var(--muted)}
.desktop-nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:10px;text-decoration:none}
.nav-toggle{background:none;border:0;font-size:1.4rem;padding:8px}
.mobile-nav{display:flex;flex-direction:column;padding:12px}
.mobile-nav a{padding:8px 0;text-decoration:none;color:var(--text)}
.hidden{display:none}

.hero{padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:36px;align-items:center}
.hero-title{font-size:2.1rem;margin:0;color:var(--text)}
.hero-sub{margin:12px 0 16px;color:var(--muted)}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{border:1px solid #eee;background:transparent;color:var(--text)}
.btn.small{padding:8px 12px;border-radius:8px}
.btn.large{padding:14px 20px;border-radius:14px}
.hero-actions{margin-top:12px}
.hero-stats{list-style:none;padding:0;margin:14px 0 0;color:var(--muted);display:flex;gap:12px;font-size:0.9rem}
.hero-art img{width:100%;height:auto;border-radius:16px}

.story{padding:36px 0}
.story-inner{display:flex;gap:24px;align-items:center}
.avatar img{width:120px;height:120px;border-radius:16px}
.story-copy h2{margin-top:0}
.muted{color:var(--muted);font-size:0.9rem}

.framework .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
.card{background:linear-gradient(180deg,#fff3f0,#fff);border-radius:12px;padding:18px;box-shadow:0 6px 18px rgba(59,130,246,0.06)}
.card h3{margin-top:0}

.programs .program-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
.prog{background:var(--card);padding:16px;border-radius:12px}

.pricing .price-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
.price-card{background:#fff;padding:16px;border-radius:12px;border:1px solid #fff7f5}
.price{font-weight:700;color:var(--accent-2)}

.testimonials .test-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
blockquote{background:#fbfcff;padding:16px;border-radius:12px;border-left:4px solid var(--accent-2)}
blockquote p{margin:0}
blockquote cite{display:block;margin-top:8px;color:var(--muted);font-size:0.9rem}

.cta{padding:28px 0}
.cta-inner{display:flex;align-items:center;justify-content:space-between;background:linear-gradient(90deg,#fff,#fff7f5);padding:20px;border-radius:14px}
.site-footer{border-top:1px solid #fff3f0;padding:28px 0;margin-top:28px}
.footer-grid{display:grid;grid-template-columns:1fr 1.6fr 1fr;gap:18px}

@media (max-width:980px){
  .hero-grid{grid-template-columns:1fr;}
  .desktop-nav{display:none}
  .nav-toggle{display:block}
  .mobile-nav{display:flex}
  .story-inner{flex-direction:column}
  .framework .grid,.programs .program-grid,.pricing .price-grid,.testimonials .test-grid{grid-template-columns:1fr}
  .cta-inner{flex-direction:column;gap:12px}
}
"} 
{"path":"assets/js/main.js","content":"// Simple interactions for the bold_playful template
document.addEventListener('DOMContentLoaded', function(){
  var toggle = document.querySelector('.nav-toggle');
  var mobile = document.querySelector('.mobile-nav');
  if(toggle && mobile){
    toggle.addEventListener('click', function(){
      mobile.classList.toggle('hidden');
      toggle.setAttribute('aria-expanded', !mobile.classList.contains('hidden'));
    });
  }

  // Smooth scroll for same-page anchors
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      var id = this.getAttribute('href');
      var el = document.querySelector(id);
      if(el){
        e.preventDefault();
        el.scrollIntoView({behavior:'smooth',block:'start'});
      }
    });
  });

  // Track simple CTA clicks for a local console log (no analytics)
  document.querySelectorAll('.btn.primary, .cta .btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      console.info('Primary CTA clicked', this.href || this.getAttribute('href'));
    });
  });

  // Small form prevention placeholder if a booking form is added later
  document.querySelectorAll('form').forEach(function(form){
    form.addEventListener('submit', function(e){
      var action = form.getAttribute('action') || '';
      // If no action, prevent accidental submissions in template
      if(!action || action === '#'){
        e.preventDefault();
        alert('This template form is a placeholder. Configure form submission in settings.');
      }
    });
  });
});
"} 
